import { lazy, Suspense } from "react";
import { BrowserRouter, Route, Routes } from "react-router-dom";
import NotFound from "./pages/NotFound";
import { OptionSwitcher, type SiteOption } from "@/components/OptionSwitcher";
import P1 from "@/sections/01-page";
const load2 = () => import("@/sections/02-page");
const P2 = lazy(load2);
const load3 = () => import("@/sections/03-page");
const P3 = lazy(load3);

// Options built for this brief (generated by the website engine: npm run site -- switcher <slug>).
const OPTIONS: SiteOption[] = [
  { path: "/", number: "01", name: "Modern & Playful", tagline: "Most playful and energetic of the ten, with a bright friendly tone that suits a family pet brand.", swatches: ["#0b5ed7","#e0a200","#0d6efd"] },
  { path: "/option-2", number: "02", name: "Soft & Modern", tagline: "Friendly, trust-led booking page; its 'care pathway' story fits gentle, certified pet handling.", swatches: ["#ffffff","#0ea5a0","#0c8e8a"], preload: load2 },
  { path: "/option-3", number: "03", name: "Elegant & Soft", tagline: "Salon layout maps directly to grooming services and appointments; easy to warm up with teal and yellow.", swatches: ["#1e7b44","#c96f7a","#b25460"], preload: load3 },
];

const App = () => (
  <BrowserRouter>
    <Suspense fallback={<div style={{ minHeight: "100vh" }} />}>
      <Routes>
        <Route path="/" element={<P1 />} />
        <Route path="/option-2" element={<P2 />} />
        <Route path="/option-3" element={<P3 />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </Suspense>
    <OptionSwitcher options={OPTIONS} brand={"Paws & Bubbles"} kind="homepage" accent="#6ec6c1" />
  </BrowserRouter>
);

export default App;
